// Package lru provides a fixed-capacity least-recently-used cache.
package lru

// maxInitialCapacity bounds the map preallocation so huge capacities do not
// reserve memory that may never be used.
const maxInitialCapacity = 1 << 16

type entry[K comparable, V any] struct {
	key        K
	value      V
	prev, next *entry[K, V]
}

// Cache is a fixed-capacity LRU cache. Get, Set and Delete all run in O(1)
// expected time. Both Get hits and Set mark the key as most recently used.
//
// A Cache is not safe for concurrent use.
type Cache[K comparable, V any] struct {
	capacity int
	entries  map[K]*entry[K, V]
	// root is a sentinel of a circular doubly linked list: root.next is the
	// most recently used entry and root.prev the least recently used.
	root entry[K, V]
}

// New returns an empty cache holding at most capacity keys. It panics if
// capacity is not positive.
func New[K comparable, V any](capacity int) *Cache[K, V] {
	if capacity < 1 {
		panic("lru: capacity must be positive")
	}
	c := &Cache[K, V]{
		capacity: capacity,
		entries:  make(map[K]*entry[K, V], min(capacity, maxInitialCapacity)),
	}
	c.root.prev = &c.root
	c.root.next = &c.root
	return c
}

// Get returns the value stored for key and whether it was present. A hit
// makes key the most recently used.
func (c *Cache[K, V]) Get(key K) (V, bool) {
	e, ok := c.entries[key]
	if !ok {
		var zero V
		return zero, false
	}
	c.moveToFront(e)
	return e.value, true
}

// Set inserts or overwrites key, making it the most recently used. If the
// cache then holds more than its capacity, the least recently used key is
// evicted.
func (c *Cache[K, V]) Set(key K, value V) {
	if e, ok := c.entries[key]; ok {
		e.value = value
		c.moveToFront(e)
		return
	}
	var e *entry[K, V]
	if len(c.entries) >= c.capacity {
		// Evict the oldest entry and recycle its node for the new key.
		e = c.root.prev
		c.unlink(e)
		delete(c.entries, e.key)
	} else {
		e = new(entry[K, V])
	}
	e.key, e.value = key, value
	c.pushFront(e)
	c.entries[key] = e
}

// Delete removes key and reports whether it was present.
func (c *Cache[K, V]) Delete(key K) bool {
	e, ok := c.entries[key]
	if !ok {
		return false
	}
	c.unlink(e)
	delete(c.entries, key)
	return true
}

// Len returns the number of keys held.
func (c *Cache[K, V]) Len() int {
	return len(c.entries)
}

func (c *Cache[K, V]) moveToFront(e *entry[K, V]) {
	if c.root.next == e {
		return
	}
	c.unlink(e)
	c.pushFront(e)
}

func (c *Cache[K, V]) unlink(e *entry[K, V]) {
	e.prev.next = e.next
	e.next.prev = e.prev
	e.prev, e.next = nil, nil
}

func (c *Cache[K, V]) pushFront(e *entry[K, V]) {
	e.prev = &c.root
	e.next = c.root.next
	c.root.next.prev = e
	c.root.next = e
}

package lru

import "testing"

func TestEvictionOrder(t *testing.T) {
	c := New[string, string](2)
	c.Set("a", "1")
	c.Set("b", "2")
	if v, ok := c.Get("a"); !ok || v != "1" {
		t.Fatalf("Get(a) = %q, %v", v, ok)
	}
	c.Set("c", "3")
	if _, ok := c.Get("b"); ok {
		t.Fatal("b should have been evicted")
	}
	if n := c.Len(); n != 2 {
		t.Fatalf("Len = %d, want 2", n)
	}
}

func TestOverwriteRefreshes(t *testing.T) {
	c := New[string, string](2)
	c.Set("a", "1")
	c.Set("b", "2")
	c.Set("a", "9")
	c.Set("c", "3")
	if v, _ := c.Get("a"); v != "9" {
		t.Fatalf("Get(a) = %q, want 9", v)
	}
	if _, ok := c.Get("b"); ok {
		t.Fatal("b should have been evicted")
	}
}

func TestDelete(t *testing.T) {
	c := New[string, string](3)
	c.Set("x", "1")
	if !c.Delete("x") {
		t.Fatal("first Delete should report presence")
	}
	if c.Delete("x") {
		t.Fatal("second Delete should report absence")
	}
	if c.Len() != 0 {
		t.Fatalf("Len = %d, want 0", c.Len())
	}
	c.Set("y", "2")
	if v, ok := c.Get("y"); !ok || v != "2" {
		t.Fatalf("Get(y) = %q, %v", v, ok)
	}
}

// Command app simulates an LRU cache driven by commands on standard input.
//
// The first line holds the capacity; each later line is one of
// "SET <key> <value>", "GET <key>", "DEL <key>" or "SIZE". Results are
// written to standard output, one per line.
package main

import (
	"bufio"
	"bytes"
	"errors"
	"fmt"
	"io"
	"os"
	"strconv"

	"lru/lru"
)

const bufferSize = 1 << 16

func main() {
	out := bufio.NewWriterSize(os.Stdout, bufferSize)
	err := run(os.Stdin, out)
	if flushErr := out.Flush(); err == nil {
		err = flushErr
	}
	if err != nil {
		fmt.Fprintln(os.Stderr, "lru:", err)
		os.Exit(1)
	}
}

func run(r io.Reader, w *bufio.Writer) error {
	sc := bufio.NewScanner(r)
	sc.Buffer(make([]byte, bufferSize), bufio.MaxScanTokenSize*16)

	if !sc.Scan() {
		return sc.Err()
	}
	capacity, err := strconv.Atoi(string(bytes.TrimSpace(sc.Bytes())))
	if err != nil {
		return fmt.Errorf("invalid capacity: %w", err)
	}
	if capacity < 1 {
		return errors.New("capacity must be positive")
	}

	cache := lru.New[string, string](capacity)
	for sc.Scan() {
		execute(cache, sc.Bytes(), w)
	}
	return sc.Err()
}

// execute applies one command line to cache. Blank or unrecognised lines are
// ignored, as are commands missing their arguments.
func execute(cache *lru.Cache[string, string], line []byte, w *bufio.Writer) {
	cmd, args, hasArgs := bytes.Cut(line, []byte{' '})
	switch string(cmd) {
	case "SET":
		key, value, ok := bytes.Cut(args, []byte{' '})
		if !hasArgs || !ok {
			return
		}
		cache.Set(string(key), string(value))
	case "GET":
		if !hasArgs {
			return
		}
		if value, ok := cache.Get(string(args)); ok {
			w.WriteString(value)
		} else {
			w.WriteString("NULL")
		}
		w.WriteByte('\n')
	case "DEL":
		if !hasArgs {
			return
		}
		if cache.Delete(string(args)) {
			w.WriteString("1\n")
		} else {
			w.WriteString("0\n")
		}
	case "SIZE":
		w.Write(strconv.AppendInt(w.AvailableBuffer(), int64(cache.Len()), 10))
		w.WriteByte('\n')
	}
}
